//! Native Playwright client over the official driver.
//!
//! [`protocol`] is generated by `scripts/generate-playwright-protocol.mjs`
//! from Playwright's `protocol.yml` (vendored in `rust/protocol/playwright`):
//! one typed struct per protocol interface, with a typed method per command
//! and a typed enum of its events. [`connection`] runs the conversation and
//! [`driver`] starts `playwright-core`'s `run-driver` through command-stream.

pub mod connection;
pub mod driver;
#[rustfmt::skip]
pub mod protocol;
pub mod transport;

pub use connection::{Channel, ChannelType, Connection, ObjectRef, ProtocolError, Ref};
pub use driver::{DriverLocation, DriverOptions, PlaywrightDriver};
